local ____Logger = require("lib.Logger")
local LogLevel = ____Logger.LogLevel
function ____exports.startErrorReport(self, ____bindingPattern0)
    local ____error
    local log
    local display
    local runtime
    runtime = ____bindingPattern0.runtime
    display = ____bindingPattern0.display
    log = ____bindingPattern0.log
    ____error = ____bindingPattern0.error
    local pluginEnv = runtime.pluginEnv
    local pluginName = pluginEnv.pluginName
    local isOnPC = HostType() == "onPC"
    local isConsole = HostType() == "Console"
    local title = ((((pluginName .. " (v") .. pluginEnv.pluginVersion) .. "): ERROR ! (MA3 ") .. Version()) .. ")"
    local errorMsg = ("Oops, this error just occured:\n\n" .. ____error.message) .. "\n\n"
    local EMAIL = "hepi@ma3-pro-plugins.com"
    local startDialogs
    startDialogs = function()
        local instructionSteps = {}
        instructionSteps[#instructionSteps + 1] = "Please make a screenshot of this error dialog"
        local connectedUSBStorageDevices = MAUtils:getConnectedUSBStorageDevices()
        local isUSBStorageDeviceConnected = #connectedUSBStorageDevices > 0
        local function stepsToMessage(self, instructionSteps)
            return table.concat(
                __TS__ArrayMap(
                    instructionSteps,
                    function(____, stepMsg, index) return (tostring(index + 1) .. ") ") .. stepMsg end
                ),
                "\n\n"
            )
        end
        local logFilePath = "[Unresolved]"
        if SupportedFeatures.system.dumpLogToSystemMonitorFolder then
            if isUSBStorageDeviceConnected then
                if #connectedUSBStorageDevices == 1 then
                    local mountPoint = connectedUSBStorageDevices[1]:Get("mountPoint")
                    logFilePath = FileUtils:path(mountPoint, MAUtils.usbSystemMonitorPath)
                    instructionSteps[#instructionSteps + 1] = "Click OK to DumpLog"
                    instructionSteps[#instructionSteps + 1] = "Locate the latest log file at: " .. FileUtils:path(
                        mountPoint,
                        MAUtils.usbSystemMonitorPath,
                        MAUtils:createSystemMonitorLogFileName()
                    )
                else
                    logFilePath = MAUtils.usbSystemMonitorPath
                    instructionSteps[#instructionSteps + 1] = "Click OK to DumpLog, and choose which USB stick to use"
                    instructionSteps[#instructionSteps + 1] = "Locate the latest log file at [CHOSEN DRIVE]/" .. FileUtils:path(
                        MAUtils.usbSystemMonitorPath,
                        MAUtils:createSystemMonitorLogFileName()
                    )
                end
            else
                local SYSTEM_MONITOR_FOLDER_NAME = "system_monitor"
                local LOCAL_SYSTEM_MONITOR_PATH = FileUtils:path(
                    GetPath(Enums.PathType.Library),
                    SYSTEM_MONITOR_FOLDER_NAME
                )
                if isOnPC then
                    logFilePath = LOCAL_SYSTEM_MONITOR_PATH
                    instructionSteps[#instructionSteps + 1] = "Click OK to DumpLog"
                    instructionSteps[#instructionSteps + 1] = "Locate the latest log file at: " .. FileUtils:path(
                        LOCAL_SYSTEM_MONITOR_PATH,
                        MAUtils:createSystemMonitorLogFileName()
                    )
                elseif isConsole then
                    local localInstructions = {table.unpack(instructionSteps)}
                    localInstructions[#localInstructions + 1] = "Please connect a USB stick in order to dump the log file, and press OK."
                    local instructionsMsg = stepsToMessage(nil, localInstructions)
                    local userConfirmed = showConfirm(nil, display.index, title, errorMsg .. instructionsMsg)
                    if userConfirmed then
                        startDialogs(nil)
                        return
                    else
                        return
                    end
                else
                    logFilePath = LOCAL_SYSTEM_MONITOR_PATH
                    instructionSteps[#instructionSteps + 1] = "Click OK to DumpLog"
                end
            end
        else
            logFilePath = GetPath(Enums.PathType.CrashLog)
            if isOnPC then
                instructionSteps[#instructionSteps + 1] = "Click OK to DumpLog"
                instructionSteps[#instructionSteps + 1] = "Locate the latest log file at: " .. FileUtils:path(
                    logFilePath,
                    MAUtils:createSystemMonitorLogFileName()
                )
                instructionSteps[#instructionSteps + 1] = "If you happen to restart MA3 before locating the log file, then you can find itin the \"processed\" folder: " .. FileUtils:path(
                    logFilePath,
                    "processed",
                    MAUtils:createSystemMonitorLogFileName()
                )
            elseif isConsole then
                instructionSteps[#instructionSteps + 1] = "Click OK to DumpLog"
                instructionSteps[#instructionSteps + 1] = "If this is very important, contact me at hepi@ma3-pro-plugins.com, and we might try at extract the log file using FTP."
                instructionSteps[#instructionSteps + 1] = "Alternatively, clean the screen, open a new big SystemMonitor window, scroll to find ERROR lines, and take a screenshot."
            end
        end
        instructionSteps[#instructionSteps + 1] = "Send screenshots and log file to: " .. EMAIL
        local instructionsMsg = stepsToMessage(nil, instructionSteps)
        showAlert(nil, display.index, title, errorMsg .. instructionsMsg)
        CmdIndirectWait("DumpLog")
        showAlert(
            nil,
            display.index,
            pluginName .. ": Collect Log File",
            ("Locate the log file (.txt) that was just created. It should be under:\n\n " .. FileUtils:path(
                logFilePath,
                MAUtils:createSystemMonitorLogFileName()
            )) .. "\n\n Please send this file to:\n\n hepi@ma3-pro-plugins.com\n\nThank You !"
        )
        if log:getLogLevel() ~= LogLevel.DEBUG then
            runtime:setLogLevel(LogLevel.DEBUG)
            showAlert(nil, display.index, pluginEnv.pluginName .. ": Please Reproduce", "DEBUG logs are now enabled.\n\n Could you please reproduce the error, and send the detailed logs as well.\n\nThank you, and sorry for your trouble.")
        end
        startUI(
            nil,
            display,
            MultiActionDialog(
                nil,
                {
                    title = pluginEnv.pluginName .. ": Re-init Plugin Data?",
                    message = "If the main menu doesn't work, then the plugin's data might be corrupted. Click \"Uninstall\" to delete ALL plugin data.",
                    actions = {
                        {
                            label = "Keep going",
                            action = function() return {type = "Quit"} end
                        },
                        {
                            label = "Uninstall",
                            action = function()
                                runtime:createPlugin(display):uninstall(display, {hardCleanup = true})
                                return {type = "Quit"}
                            end
                        }
                    }
                }
            )
        )
    end
    startDialogs(nil)
end
return ____exports
 end,
